using System.Text.Json.Nodes;
using System.Security.Cryptography;

internal static class WebProgressPublishing
{
    // Only data generated by this exporter enters the static destination. No SDK/XT
    // trees, binaries, third-party docs, links or arbitrary directory sync.
    internal static void Publish(string data,string runId,string destination)
    {
        var validation=WebProgressDataValidation.Validate(data);
        if(validation["errors"]!.AsArray().Count>0)throw new InvalidDataException(validation.ToJsonString());
        var source=Path.Combine(data,"runs",runId);var runs=Path.Combine(destination,"runs");Directory.CreateDirectory(runs);
        var final=Path.Combine(runs,runId);var staging=Path.Combine(runs,".staging-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(staging);
        try
        {
            foreach(var entry in Directory.EnumerateFileSystemEntries(source,"*",SearchOption.AllDirectories))
            {
                if((File.GetAttributes(entry)&FileAttributes.ReparsePoint)!=0)throw new IOException("Symlinks are not static data: "+Path.GetFileName(entry));
                if(Directory.Exists(entry))continue;
                if(Path.GetExtension(entry) is not (".json" or ".log"))throw new IOException("Static data allowlist rejects "+Path.GetExtension(entry));
                var relative=Path.GetRelativePath(source,entry);var target=Path.Combine(staging,relative);Directory.CreateDirectory(Path.GetDirectoryName(target)!);File.Copy(entry,target);
            }
            if(Directory.Exists(final))
            {
                var existing=Directory.EnumerateFiles(final,"*",SearchOption.AllDirectories).Select(f=>Path.GetRelativePath(final,f)).Order().ToArray();
                var incoming=Directory.EnumerateFiles(staging,"*",SearchOption.AllDirectories).Select(f=>Path.GetRelativePath(staging,f)).Order().ToArray();
                if(!existing.SequenceEqual(incoming)||incoming.Any(f=>!SHA256.HashData(File.ReadAllBytes(Path.Combine(final,f))).SequenceEqual(SHA256.HashData(File.ReadAllBytes(Path.Combine(staging,f))))))throw new IOException("Refusing to replace immutable run "+runId);
                Directory.Delete(staging,true);
            }
            else Directory.Move(staging,final);
            var input=JsonNode.Parse(File.ReadAllText(Path.Combine(data,"index.json")))!;
            var descriptor=input["runs"]!.AsArray().Single(r=>r!["id"]!.GetValue<string>()==runId)!.DeepClone();
            var indexPath=Path.Combine(destination,"index.json");
            var index=File.Exists(indexPath)?JsonNode.Parse(File.ReadAllText(indexPath))!.AsObject():new JsonObject{["schemaVersion"]=1,["runs"]=new JsonArray()};
            var descriptors=index["runs"]!.AsArray();var previous=descriptors.FirstOrDefault(r=>r!["id"]!.GetValue<string>()==runId);if(previous!=null)descriptors.Remove(previous);descriptors.Insert(0,descriptor);
            index["latestRunId"]=runId;index["generatedAt"]=DateTimeOffset.UtcNow.ToString("O");
            File.WriteAllText(indexPath+".tmp",index.ToJsonString());File.Move(indexPath+".tmp",indexPath,true);
        }
        finally{if(Directory.Exists(staging))Directory.Delete(staging,true);}
    }
}
